// POM68K — known divergences of a CPU vector corpus, by name.
//
// A corpus generated by an oracle holds, here and there, a vector on which the
// fork deliberately does NOT follow that oracle: an open ruling (oracle/fuzz/
// disputes/NOTES.md), or a ruling taken for a manual against the oracle.
// Dropping such vectors from the corpus hides them, and letting them fail
// makes the gate red for a decision, not for a defect. This list is the third
// way, shared by sst68030 and sst68040 (`--known FILE`):
//
//   - one vector name per line, '#' comments, grouped by ruling;
//   - a listed vector that FAILS is counted apart, neither pass nor failure;
//   - a listed vector that PASSES fails the run — the ruling was settled, or
//     something moved: the list must describe the tree, not excuse it;
//   - a listed name the corpus does not hold fails a whole-corpus run.
#pragma once

#include <cstdio>
#include <fstream>
#include <set>
#include <string>

namespace sstknown {

class List {
public:
    // False when the file cannot be opened.
    bool load(const std::string& path) {
        std::ifstream in(path);
        if (!in) return false;
        for (std::string line; std::getline(in, line);) {
            while (!line.empty() && (line.back() == '\r' || line.back() == ' ' ||
                                     line.back() == '\t'))
                line.pop_back();
            if (!line.empty() && line[0] != '#') names_.insert(line);
        }
        loaded_ = true;
        return true;
    }
    bool active() const { return loaded_; }

    // Whether `name` is listed; a listed name is remembered as met.
    bool listed(const std::string& name) {
        if (!loaded_ || !names_.count(name)) return false;
        seen_.insert(name);
        return true;
    }

    // Listed names the run never met; prints up to `examples` of them.
    long reportMissing(int examples) const {
        long missing = 0;
        for (const std::string& name : names_) {
            if (seen_.count(name)) continue;
            if (missing++ < examples)
                std::printf("        x \"%s\"  listed in --known but absent "
                            "from the corpus\n", name.c_str());
        }
        return missing;
    }

    static constexpr const char* kStale = "listed in --known but passes: remove it";

private:
    std::set<std::string> names_, seen_;
    bool loaded_ = false;
};

}  // namespace sstknown
